// Generated by AI
const jwt = require('jsonwebtoken');
let bcrypt;
try {
  bcrypt = require('bcrypt');
} catch (e) {
  bcrypt = require('bcryptjs');
}

const db = require('../config/db');
const gameEvents = require('../events/gameEvents');

const JWT_SECRET = process.env.JWT_SECRET || 'spacefuel_super_secret_jwt_key_2026_pilot_auth';

/**
 * Pilot Registration
 * POST /api/register
 */
const register = async (req, res) => {
  try {
    const { name, nickname, email, password } = req.body;

    if (!name || !nickname || !email || !password) {
      return res.status(400).json({
        success: false,
        message: 'All fields (name, nickname, email, password) are required.'
      });
    }

    const trimmedEmail = email.trim().toLowerCase();
    const trimmedName = name.trim();
    const trimmedNickname = nickname.trim();

    if (password.length < 6) {
      return res.status(400).json({
        success: false,
        message: 'Password must be at least 6 characters long.'
      });
    }

    // Check if user already exists
    const [existingUsers] = await db.query(
      'SELECT id FROM users WHERE email = ?',
      [trimmedEmail]
    );

    if (existingUsers.length > 0) {
      return res.status(409).json({
        success: false,
        message: 'This email is already registered. Please login.'
      });
    }

    // Hash password with bcrypt
    const saltRounds = 10;
    const hashedPassword = await bcrypt.hash(password, saltRounds);

    // Save to database
    const [result] = await db.query(
      'INSERT INTO users (name, nickname, email, password) VALUES (?, ?, ?, ?)',
      [trimmedName, trimmedNickname, trimmedEmail, hashedPassword]
    );

    // Emit event
    gameEvents.emit('userRegistered', {
      id: result.insertId,
      name: trimmedName,
      nickname: trimmedNickname,
      email: trimmedEmail
    });

    return res.status(201).json({
      success: true,
      message: 'Registration successful! You can now log in.',
      user: {
        id: result.insertId,
        name: trimmedName,
        nickname: trimmedNickname,
        email: trimmedEmail
      }
    });
  } catch (error) {
    console.error('Error during registration:', error);
    return res.status(500).json({
      success: false,
      message: 'Internal server error during registration.',
      error: error.message
    });
  }
};

/**
 * Pilot Login
 * POST /api/login
 */
const login = async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({
        success: false,
        message: 'Email and password are required.'
      });
    }

    const trimmedEmail = email.trim().toLowerCase();

    // Find user by email
    const [users] = await db.query(
      'SELECT id, name, nickname, email, password FROM users WHERE email = ?',
      [trimmedEmail]
    );

    if (users.length === 0) {
      return res.status(401).json({
        success: false,
        message: 'Invalid email or password.'
      });
    }

    const user = users[0];

    // Verify password with bcrypt
    const isPasswordValid = await bcrypt.compare(password, user.password);

    if (!isPasswordValid) {
      return res.status(401).json({
        success: false,
        message: 'Invalid email or password.'
      });
    }

    // Generate cryptographic JWT Token
    const token = jwt.sign(
      {
        id: user.id,
        name: user.name,
        nickname: user.nickname,
        email: user.email
      },
      JWT_SECRET,
      { expiresIn: '24h' }
    );

    // Emit event
    gameEvents.emit('userLoggedIn', {
      id: user.id,
      nickname: user.nickname,
      email: user.email
    });

    return res.status(200).json({
      success: true,
      message: 'Login successful',
      token,
      user: {
        id: user.id,
        name: user.name,
        nickname: user.nickname,
        email: user.email
      }
    });
  } catch (error) {
    console.error('Error during login:', error);
    return res.status(500).json({
      success: false,
      message: 'Internal server error during login.',
      error: error.message
    });
  }
};

/**
 * Token Verification
 * GET /api/verify-token
 */
const verifyToken = (req, res) => {
  try {
    const authHeader = req.headers['authorization'];

    if (!authHeader) {
      return res.status(401).json({
        success: false,
        message: 'No authorization token provided.'
      });
    }

    const token = authHeader.startsWith('Bearer ')
      ? authHeader.slice(7)
      : authHeader;

    const decoded = jwt.verify(token, JWT_SECRET);

    return res.status(200).json({
      success: true,
      message: 'Token verified! Pilot identity authenticated.',
      user: {
        id: decoded.id,
        name: decoded.name,
        nickname: decoded.nickname,
        email: decoded.email
      }
    });
  } catch (error) {
    return res.status(401).json({
      success: false,
      message: 'Invalid, tampered, or expired token.',
      error: error.message
    });
  }
};

module.exports = {
  register,
  login,
  verifyToken
};
